#include <bits/stdc++.h>
using namespace std;

const int MAX_INF = INT_MAX;

namespace flow_network {

const int MAX_NODES = 10001;
struct Edge { int v, p; int cap, cost; };
vector<Edge> adj[MAX_NODES];
int visited[MAX_NODES], current[MAX_NODES], total_nodes;
int dist[MAX_NODES], potential[MAX_NODES];

int createVertices(int count) {
    while (count--) adj[total_nodes++].clear();
    return total_nodes - 1;
}

void connectEdges(int u, int v, int capacity, int cost) {
    adj[u].push_back({ v, (int)adj[v].size(), capacity, cost });
    adj[v].push_back({ u, (int)adj[u].size() - 1, 0, -cost });
}

bool findShortestPath(int s, int t) {
    fill_n(dist, total_nodes, INT_MAX);
    fill_n(visited, total_nodes, 0);
    typedef pair<int, int> pii;
    priority_queue<pii, vector<pii>, greater<pii>> pq;
    pq.push({ dist[s] = 0, s });
    while (!pq.empty()) {
        int u, du; tie(du, u) = pq.top(); pq.pop();
        if (visited[u]) continue; visited[u] = 1;
        for (auto &e : adj[u]) {
            int v = e.v; int dv = du + potential[u] + e.w - potential[v];
            if (!e.c || visited[v] || dist[v] <= dv) continue;
            pq.push({ dist[v] = dv, v });
        }
    }
    return visited[t];
}

bool buildLevelGraph(int s, int t) {
    fill_n(visited, total_nodes, 0);
    queue<int> q; q.push(s); visited[s] = 1;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (auto &e : adj[u]) {
            int v = e.v;
            if (visited[v] || !e.c) continue;
            if (dist[v] != dist[u] + e.w - potential[v] + potential[u]) continue;
            visited[v] = visited[u] + 1; q.push(v);
        }
    }
    return visited[t] != 0;
}

int sendFlow(int u, int t, int flow) {
    if (u == t) return flow;
    int totalSent = 0;
    for (int &i = current[u]; i < (int)adj[u].size(); ++i) {
        auto &e = adj[u][i]; int v = e.v;
        if (!e.c || visited[v] != visited[u] + 1) continue;
        if (dist[v] != dist[u] + e.w - potential[v] + potential[u]) continue;
        int pushed = sendFlow(v, t, min(e.c, flow));
        totalSent += pushed; flow -= pushed; e.c -= pushed; adj[v][e.p].c += pushed;
        if (!flow) break;
    }
    return totalSent;
}

pair<int, int> computeMaxFlow(int s, int t, int maxFlow) {
    int totalFlow = 0, totalCost = 0;
    fill_n(potential, total_nodes, 0);
    while (findShortestPath(s, t)) {
        int flow = 0;
        while (buildLevelGraph(s, t)) {
            fill_n(current, total_nodes, 0);
            int pushedFlow = sendFlow(s, t, maxFlow);
            maxFlow -= pushedFlow; flow += pushedFlow;
            if (!maxFlow) break;
        }
        totalFlow += flow; totalCost += (dist[t] + potential[t]) * flow;
        for (int i = 0; i < total_nodes; ++i) potential[i] += dist[i];
        if (!maxFlow) break;
    }
    return { totalFlow, totalCost };
}

}

int main() {
    int n, m, k, c, d;
    scanf("%d %d %d %d %d", &n, &m, &k, &c, &d);
    int totalVertices = max(n, k) * 2;
    flow_network::createVertices(totalVertices * n);
    int s = flow_network::createVertices(1), t = flow_network::createVertices(1);
    for (int j = 0; j < k; ++j) {
        int a; scanf("%d", &a);
        a--;
        flow_network::connectEdges(s, a, 1, 0);
    }
    for (int z = 1; z <= m; ++z) {
        int u, v; scanf("%d %d", &u, &v);
        u--; v--;
        for (int i = 0; i + 1 < totalVertices; ++i) {
            int u1 = u + i * n, v1 = v + (i + 1) * n;
            int u2 = u + (i + 1) * n, v2 = v + i * n;
            for (int j = 0; j < k; ++j) {
                flow_network::connectEdges(u1, v1, 1, c + d * (2 * j + 1));
                flow_network::connectEdges(v2, u2, 1, c + d * (2 * j + 1));
            }
        }
    }
    for (int i = 0; i + 1 < totalVertices; ++i) {
        for (int j = 0; j < n; ++j) {
            int u = j + i * n, v = j + (i + 1) * n;
            flow_network::connectEdges(u, v, INT_MAX, c);
        }
    }
    for (int i = 0; i < totalVertices; ++i)
        flow_network::connectEdges(i * n, t, INT_MAX, 0);
    printf("%d\n", flow_network::computeMaxFlow(s, t, INT_MAX).second);
    return 0;
}
